import 'package:flutter/material.dart';
import '../services/app_services.dart';
class AuthScreen extends StatefulWidget{const AuthScreen({super.key});State<AuthScreen> createState()=>_AuthState();}
class _AuthState extends State<AuthScreen>{final phone=TextEditingController(),otp=TextEditingController();final a=AuthService();bool sent=false,loading=false;String? err;
Widget field(TextEditingController c,String hint)=>TextField(controller:c,keyboardType:TextInputType.phone,decoration:InputDecoration(labelText:hint,prefixIcon:const Icon(Icons.phone),filled:true,fillColor:Colors.white));
Future<void> go()async{setState(()=>loading=true);try{if(!sent){await a.sendOtp(phone.text.trim(),(_)=>setState(()=>sent=true));}else{await a.verifyOtp(otp.text.trim());}}catch(e){setState(()=>err=e.toString());}finally{setState(()=>loading=false);}}
Widget build(BuildContext c)=>Scaffold(body:Center(child:ConstrainedBox(constraints:const BoxConstraints(maxWidth:430),child:Padding(padding:const EdgeInsets.all(24),child:Column(mainAxisAlignment:MainAxisAlignment.center,crossAxisAlignment:CrossAxisAlignment.stretch,children:[const Icon(Icons.home_work_rounded,size:64),const SizedBox(height:16),Text('KothaFinder Nepal',textAlign:TextAlign.center,style:TextStyle(fontSize:30,fontWeight:FontWeight.bold)),const SizedBox(height:8),const Text('Find a room. List a room. Connect directly.',textAlign:TextAlign.center),const SizedBox(height:32),field(phone,'Mobile number (+977...)'),if(sent)...[const SizedBox(height:12),field(otp,'6-digit OTP')],if(err!=null)Padding(padding:const EdgeInsets.all(8),child:Text(err!,style:const TextStyle(color:Colors.red))),const SizedBox(height:12),FilledButton(onPressed:loading?null:go,child:Text(loading?'Please wait...':sent?'Verify OTP':'Send OTP'))]))));}
}
